import{_ as e,c as r,o as i,af as n}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"41、【損】 兌下艮上","description":"溫公易說 - 41、【損】 兌下艮上","frontmatter":{"title":"41、【損】 兌下艮上","description":"溫公易說 - 41、【損】 兌下艮上"},"headers":[],"relativePath":"classics/wengong/042.md","filePath":"classics/wengong/042.md"}'),l={name:"classics/wengong/042.md"};function t(h,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[n('<h1 id="_41、【損】-兌下艮上" tabindex="-1">41、【損】 兌下艮上 <a class="header-anchor" href="#_41、【損】-兌下艮上" aria-label="Permalink to “41、【損】 兌下艮上”">​</a></h1><p>損益之名以內為主者也，內為已，外為彼。</p><h3 id="彖曰-損-損下益上-其道上行。損而有孚-元吉-無咎-可貞。利有攸往。曷之用-二簋-可用享。二簋-應有時。損剛益柔-有時損益盈虛-與時偕行。" tabindex="-1">彖曰：損，損下益上，其道上行。損而有孚，元吉，無咎，可貞。利有攸往。曷之用？二簋，可用享。二簋，應有時。損剛益柔，有時損益盈虛，與時偕行。 <a class="header-anchor" href="#彖曰-損-損下益上-其道上行。損而有孚-元吉-無咎-可貞。利有攸往。曷之用-二簋-可用享。二簋-應有時。損剛益柔-有時損益盈虛-與時偕行。" aria-label="Permalink to “彖曰：損，損下益上，其道上行。損而有孚，元吉，無咎，可貞。利有攸往。曷之用？二簋，可用享。二簋，應有時。損剛益柔，有時損益盈虛，與時偕行。”">​</a></h3><h3 id="象曰-山下有澤-損。君子以懲忿窒欲。" tabindex="-1">象曰：山下有澤，損。君子以懲忿窒欲。 <a class="header-anchor" href="#象曰-山下有澤-損。君子以懲忿窒欲。" aria-label="Permalink to “象曰：山下有澤，損。君子以懲忿窒欲。”">​</a></h3><h3 id="初九-已事遄往-無咎。酌損之-象曰-已事遄往-尚合志也。" tabindex="-1">初九：已事遄往，無咎。酌損之 象曰：已事遄往，尚合志也。 <a class="header-anchor" href="#初九-已事遄往-無咎。酌損之-象曰-已事遄往-尚合志也。" aria-label="Permalink to “初九：已事遄往，無咎。酌損之 象曰：已事遄往，尚合志也。”">​</a></h3><h3 id="九二-利貞-徵兇。弗損益之-象曰-九二利貞-中以為志也。" tabindex="-1">九二：利貞，徵兇。弗損益之 象曰：九二利貞，中以為志也。 <a class="header-anchor" href="#九二-利貞-徵兇。弗損益之-象曰-九二利貞-中以為志也。" aria-label="Permalink to “九二：利貞，徵兇。弗損益之 象曰：九二利貞，中以為志也。”">​</a></h3><h3 id="六三-三人行則損-一人行則得其友-象曰-一人行-三則疑也。" tabindex="-1">六三：三人行則損，一人行則得其友 象曰：一人行，三則疑也。 <a class="header-anchor" href="#六三-三人行則損-一人行則得其友-象曰-一人行-三則疑也。" aria-label="Permalink to “六三：三人行則損，一人行則得其友 象曰：一人行，三則疑也。”">​</a></h3><h3 id="六四-損其疾-使遄有喜-無咎-象曰-損其疾-亦可喜也。" tabindex="-1">六四：損其疾，使遄有喜，無咎 象曰：損其疾，亦可喜也。 <a class="header-anchor" href="#六四-損其疾-使遄有喜-無咎-象曰-損其疾-亦可喜也。" aria-label="Permalink to “六四：損其疾，使遄有喜，無咎 象曰：損其疾，亦可喜也。”">​</a></h3><h3 id="六五-或益之-十朋之龜-弗克違-元吉-象曰-六五元吉-自上佑也。" tabindex="-1">六五：或益之，十朋之龜，弗克違，元吉 象曰：六五元吉，自上佑也。 <a class="header-anchor" href="#六五-或益之-十朋之龜-弗克違-元吉-象曰-六五元吉-自上佑也。" aria-label="Permalink to “六五：或益之，十朋之龜，弗克違，元吉 象曰：六五元吉，自上佑也。”">​</a></h3><h3 id="上九-弗損益之-無咎-貞吉。利有攸往-得臣無家-象曰-弗損益之-大得志也。" tabindex="-1">上九：弗損益之，無咎，貞吉。利有攸往，得臣無家 象曰：弗損益之，大得志也。 <a class="header-anchor" href="#上九-弗損益之-無咎-貞吉。利有攸往-得臣無家-象曰-弗損益之-大得志也。" aria-label="Permalink to “上九：弗損益之，無咎，貞吉。利有攸往，得臣無家 象曰：弗損益之，大得志也。”">​</a></h3>',10)])])}const f=e(l,[["render",t]]);export{b as __pageData,f as default};
